-- Aprenda se Divertindo · 74 · Cartões da trilha Policial · parte 4 de 5 (cartões 1000301 a 1000400)
-- Cole no SQL Editor e clique em Run. Pode rodar de novo sem problema. Rode as partes em ordem (a parte 1 cria a tabela).

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 1000301, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "Quais as penalidades da Lei 8.112/1990?", "verso": "Advertência, suspensão, demissão, cassação de aposentadoria ou disponibilidade, destituição de cargo em comissão e destituição de função comissionada.", "explicacao": "Lei 8.112/1990, art. 127."}, {"id": 1000302, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "Qual o prazo máximo da suspensão disciplinar na Lei 8.112?", "verso": "90 dias.", "explicacao": "Lei 8.112/1990, art. 130."}, {"id": 1000303, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pares", "frente": "Sindicância x processo administrativo disciplinar (PAD).", "verso": "Sindicância: pode resultar em arquivamento, advertência ou suspensão de até 30 dias. PAD: obrigatório para suspensão acima de 30 dias, demissão e cassação.", "explicacao": "Lei 8.112/1990, arts. 145 e 146."}, {"id": 1000304, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "Qual o prazo para concluir o PAD?", "verso": "60 dias, prorrogáveis por igual período.", "explicacao": "Lei 8.112/1990, art. 152."}, {"id": 1000305, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "certo_errado", "frente": "Certo ou errado? A falta de defesa técnica por advogado no PAD ofende a Constituição.", "verso": "Errado.", "explicacao": "Súmula Vinculante 5 do STF."}, {"id": 1000306, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "A absolvição criminal sempre impede a punição administrativa?", "verso": "Não. Só quando a absolvição negar a existência do fato ou a autoria.", "explicacao": "Lei 8.112/1990, art. 126."}, {"id": 1000307, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pares", "frente": "Cargo efetivo x cargo em comissão.", "verso": "Efetivo: provido por concurso, gera estabilidade. Comissão: livre nomeação e exoneração, para direção, chefia e assessoramento.", "explicacao": "CF, art. 37, II e V."}, {"id": 1000308, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pergunta", "frente": "Qual o prazo para o servidor nomeado tomar posse e, depois, entrar em exercício (Lei 8.112)?", "verso": "Posse: 30 dias da nomeação. Exercício: 15 dias da posse.", "explicacao": "Lei 8.112/1990, arts. 13, § 1º, e 15, § 1º."}, {"id": 1000309, "trilha": "policial", "materia": "adm", "assunto": "Licitações", "tipo": "pergunta", "frente": "Quais as modalidades de licitação na Lei 14.133/2021?", "verso": "Pregão, concorrência, concurso, leilão e diálogo competitivo.", "explicacao": "Lei 14.133/2021, art. 28. Acabaram tomada de preços e convite."}, {"id": 1000310, "trilha": "policial", "materia": "adm", "assunto": "Licitações", "tipo": "pares", "frente": "Licitação dispensável x inexigível.", "verso": "Dispensável: a competição é possível, mas a lei permite não licitar. Inexigível: a competição é inviável (ex.: fornecedor exclusivo).", "explicacao": "Lei 14.133/2021, arts. 74 e 75."}, {"id": 1000311, "trilha": "policial", "materia": "adm", "assunto": "Controle", "tipo": "pergunta", "frente": "O Judiciário pode controlar o mérito do ato administrativo?", "verso": "Não. Controla a legalidade, inclusive a razoabilidade e proporcionalidade, mas não substitui a conveniência e oportunidade do administrador.", "explicacao": "Princípio da separação dos Poderes."}, {"id": 1000312, "trilha": "policial", "materia": "adm", "assunto": "Bens públicos", "tipo": "pergunta", "frente": "Quais as características dos bens públicos?", "verso": "Inalienabilidade (relativa), imprescritibilidade (não sofrem usucapião), impenhorabilidade e não onerabilidade.", "explicacao": "CF, arts. 183, § 3º, e 191, parágrafo único."}, {"id": 1000313, "trilha": "policial", "materia": "adm", "assunto": "Serviços públicos", "tipo": "pares", "frente": "Concessão x permissão de serviço público.", "verso": "Concessão: contrato, por concorrência ou diálogo competitivo, com pessoa jurídica ou consórcio. Permissão: contrato de adesão, precário, com pessoa física ou jurídica.", "explicacao": "Lei 8.987/1995, art. 2º."}, {"id": 1000314, "trilha": "policial", "materia": "adm", "assunto": "Agentes públicos", "tipo": "pergunta", "frente": "O policial que age no exercício da função representa quem perante terceiros?", "verso": "O próprio Estado, segundo a teoria do órgão (imputação): seus atos são imputados à pessoa jurídica.", "explicacao": "Teoria de Otto Gierke."}, {"id": 1000315, "trilha": "policial", "materia": "adm", "assunto": "Processo administrativo", "tipo": "pergunta", "frente": "Qual o prazo geral para recurso administrativo na Lei 9.784?", "verso": "10 dias.", "explicacao": "Lei 9.784/1999, art. 59."}, {"id": 1000316, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "pergunta", "frente": "Qual a regra básica da crase?", "verso": "Ocorre quando a preposição “a” se junta ao artigo feminino “a(s)”, ou ao “a” inicial de aquele(s), aquela(s), aquilo.", "explicacao": "Teste: troque por uma palavra masculina. Se virar “ao”, há crase: “fui à delegacia / fui ao fórum”."}, {"id": 1000317, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "certo_errado", "frente": "Certo ou errado? Há crase em “Ele começou a estudar”.", "verso": "Errado. Não há crase antes de verbo.", "explicacao": "Também não há antes de palavra masculina (salvo “à moda de”) e de pronomes como ela, esta, você."}, {"id": 1000318, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "pergunta", "frente": "Usa-se crase em “às vezes”, “à noite” e “à medida que”?", "verso": "Sim. São locuções adverbiais e conjuntivas femininas.", "explicacao": "Locuções femininas levam crase: às pressas, à tarde, à custa de."}, {"id": 1000319, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "certo_errado", "frente": "Certo ou errado? “Chegou a uma conclusão” leva crase.", "verso": "Errado. Não há crase antes do artigo indefinido “uma”.", "explicacao": "Exceção: indicando hora (“à uma hora”)."}, {"id": 1000320, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "pergunta", "frente": "Crase antes de nome de cidade: como saber?", "verso": "Use o teste “volto de / volto da”. Se voltar DA, há crase (vou à Bahia); se voltar DE, não há (vou a Salvador).", "explicacao": "Com cidade especificada há crase: “vou à Salvador antiga”."}, {"id": 1000321, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "certo_errado", "frente": "Certo ou errado? “Haviam muitos candidatos na sala.”", "verso": "Errado. O verbo haver, no sentido de existir, é impessoal: “Havia muitos candidatos”.", "explicacao": "O verbo auxiliar acompanha: “Deve haver muitos candidatos”."}, {"id": 1000322, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "certo_errado", "frente": "Certo ou errado? “Fazem dois anos que estudo para concurso.”", "verso": "Errado. Fazer indicando tempo decorrido é impessoal: “Faz dois anos”.", "explicacao": "Mesmo caso de “haver” indicando tempo: “Há dois anos”."}, {"id": 1000323, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "Com a partícula “se” apassivadora, como fica o verbo: “Vende(m)-se casas”?", "verso": "“Vendem-se casas”: o verbo concorda com o sujeito (casas são vendidas).", "explicacao": "Com verbo que pede preposição, o “se” indetermina o sujeito e o verbo fica no singular: “Precisa-se de vendedores”."}, {"id": 1000324, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "certo_errado", "frente": "Certo ou errado? “Seguem anexo os documentos.”", "verso": "Errado. “Anexo” é adjetivo e concorda: “Seguem anexos os documentos”.", "explicacao": "“Em anexo” é invariável."}, {"id": 1000325, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "“Meio” no sentido de “um pouco” varia? “Ela está meio cansada.”", "verso": "Não varia: é advérbio. “Meia” só quando significa metade (meia hora).", "explicacao": "Mesma lógica para “bastante” (advérbio, invariável) e “menos” (sempre invariável)."}, {"id": 1000326, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "“É proibido entrada” ou “É proibida a entrada”?", "verso": "As duas estão certas. Sem artigo, fica invariável; com artigo, concorda.", "explicacao": "Vale para “é necessário”, “é bom”, “é permitido”."}, {"id": 1000327, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "Assistir no sentido de ver pede preposição?", "verso": "Sim: “assistir ao jogo”.", "explicacao": "Assistir no sentido de ajudar é transitivo direto: “o médico assistiu o paciente”."}, {"id": 1000328, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "Qual a regência correta de “preferir”?", "verso": "Preferir algo A outra coisa: “Prefiro estudar a dormir”.", "explicacao": "É errado “prefiro mais… do que…”."}, {"id": 1000329, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "Qual a regência de “obedecer”?", "verso": "Pede a preposição “a”: “obedecer ao regulamento”.", "explicacao": "Desobedecer também: “desobedecer à ordem”."}, {"id": 1000330, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "Qual a regência de “aspirar” no sentido de desejar?", "verso": "Pede a preposição “a”: “aspiro ao cargo”.", "explicacao": "No sentido de respirar/sorver, é direto: “aspirar o ar”."}, {"id": 1000331, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "“Implicar” no sentido de acarretar pede preposição?", "verso": "Não: “A decisão implica prejuízos” (sem “em”).", "explicacao": "Implicar com alguém (antipatizar) pede “com”."}, {"id": 1000332, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "“Chegar” pede qual preposição?", "verso": "A preposição “a”: “Chegou à delegacia”, “chegou a Brasília”.", "explicacao": "Na norma-padrão, evite “chegou na delegacia”."}, {"id": 1000333, "trilha": "policial", "materia": "port", "assunto": "Colocação pronominal", "tipo": "pergunta", "frente": "O que atrai o pronome para antes do verbo (próclise)?", "verso": "Palavras negativas, pronomes relativos, advérbios, conjunções subordinativas, pronomes indefinidos e interrogativos.", "explicacao": "Ex.: “Não me disseram”, “quem te contou”, “aqui se estuda”."}, {"id": 1000334, "trilha": "policial", "materia": "port", "assunto": "Colocação pronominal", "tipo": "certo_errado", "frente": "Certo ou errado? Na norma-padrão, pode-se começar frase com pronome oblíquo: “Me disseram a verdade.”", "verso": "Errado. Não se inicia período com pronome oblíquo átono: “Disseram-me a verdade”.", "explicacao": "Uso aceito na fala, mas não na norma-padrão."}, {"id": 1000335, "trilha": "policial", "materia": "port", "assunto": "Colocação pronominal", "tipo": "pergunta", "frente": "Pode haver ênclise com verbo no futuro do presente ou do pretérito?", "verso": "Não. Usa-se mesóclise (“far-se-á”) ou próclise, se houver atrativo (“não se fará”).", "explicacao": "A ênclise com futuro é sempre errada."}, {"id": 1000336, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "certo_errado", "frente": "Certo ou errado? Pode-se separar sujeito e verbo por vírgula: “Os candidatos aprovados, foram convocados.”", "verso": "Errado. Não se separa sujeito do verbo com vírgula.", "explicacao": "Só se houver termo intercalado entre duas vírgulas."}, {"id": 1000337, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "pergunta", "frente": "O vocativo deve vir isolado por vírgula?", "verso": "Sim: “Maria, venha aqui.”", "explicacao": "Vocativo é o termo usado para chamar o interlocutor."}, {"id": 1000338, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "pergunta", "frente": "Oração adjetiva explicativa x restritiva: o que muda na pontuação?", "verso": "A explicativa vem entre vírgulas e generaliza. A restritiva vem sem vírgulas e delimita.", "explicacao": "“Os alunos, que estudaram, passaram” (todos estudaram) x “Os alunos que estudaram passaram” (só alguns)."}, {"id": 1000339, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "pergunta", "frente": "Deve-se usar vírgula antes de “e”?", "verso": "Em regra, não. Usa-se quando os sujeitos são diferentes, com “e” repetido (polissíndeto) ou com valor adversativo.", "explicacao": "“Ele estudou muito, e o irmão não abriu um livro.”"}, {"id": 1000340, "trilha": "policial", "materia": "port", "assunto": "Conjunções", "tipo": "pares", "frente": "Conjunções adversativas x concessivas.", "verso": "Adversativas ligam ideias opostas em orações coordenadas: mas, porém, contudo, todavia, entretanto. Concessivas introduzem uma ressalva que não impede o fato: embora, ainda que, conquanto, mesmo que.", "explicacao": "Embora pede subjuntivo: “Embora estude, não passa”."}, {"id": 1000341, "trilha": "policial", "materia": "port", "assunto": "Conjunções", "tipo": "pergunta", "frente": "Que ideia expressam “portanto”, “logo” e “por conseguinte”?", "verso": "Conclusão.", "explicacao": "São conjunções coordenativas conclusivas."}, {"id": 1000342, "trilha": "policial", "materia": "port", "assunto": "Conjunções", "tipo": "pergunta", "frente": "Que ideia expressa “à medida que”?", "verso": "Proporção.", "explicacao": "“Na medida em que” indica causa."}, {"id": 1000343, "trilha": "policial", "materia": "port", "assunto": "Conjunções", "tipo": "pergunta", "frente": "Que ideia expressa “conforme” em “Conforme previsto, a prova foi adiada”?", "verso": "Conformidade.", "explicacao": "Equivale a “como”, “segundo”, “consoante”."}, {"id": 1000344, "trilha": "policial", "materia": "port", "assunto": "Conjunções", "tipo": "pergunta", "frente": "Que ideia expressa “desde que” em “Pode sair, desde que volte cedo”?", "verso": "Condição.", "explicacao": "Também pode indicar tempo: “Desde que chegou, não parou”."}, {"id": 1000345, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Por que x porque x por quê x porquê.", "verso": "Por que: perguntas e “pelo qual”. Porque: explicação/causa. Por quê: no fim da frase. Porquê: substantivo (“o porquê”).", "explicacao": "“Não sei por que faltou” = “o motivo pelo qual”."}, {"id": 1000346, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Mal x mau.", "verso": "Mal é o oposto de bem. Mau é o oposto de bom.", "explicacao": "“Ele agiu mal” / “Ele é um mau policial”."}, {"id": 1000347, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Onde x aonde.", "verso": "Onde: lugar em que se está (verbos estáticos). Aonde: lugar para onde se vai (verbos de movimento).", "explicacao": "“Onde você mora?” / “Aonde você vai?”."}, {"id": 1000348, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Ratificar x retificar.", "verso": "Ratificar: confirmar. Retificar: corrigir.", "explicacao": "Clássico de prova."}, {"id": 1000349, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Mandado x mandato.", "verso": "Mandado: ordem judicial (mandado de prisão). Mandato: período de exercício de cargo eletivo ou procuração.", "explicacao": "“Cumprir mandado de busca” / “mandato de deputado”."}, {"id": 1000350, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Deferir x diferir.", "verso": "Deferir: atender, conceder. Diferir: adiar ou diferenciar.", "explicacao": "“O juiz deferiu o pedido”."}, {"id": 1000351, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Infligir x infringir.", "verso": "Infligir: aplicar pena ou castigo. Infringir: violar, transgredir.", "explicacao": "“Infringiu a lei e o juiz lhe infligiu a pena”."}, {"id": 1000352, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Ao encontro de x de encontro a.", "verso": "Ao encontro de: a favor, concordância. De encontro a: contra, choque.", "explicacao": "“A proposta veio ao encontro dos meus interesses”."}, {"id": 1000353, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Acerca de x a cerca de x há cerca de.", "verso": "Acerca de: sobre, a respeito de. A cerca de: aproximadamente (distância/futuro). Há cerca de: faz aproximadamente (tempo passado).", "explicacao": "“Falou acerca do crime”; “fica a cerca de 2 km”; “chegou há cerca de 1 hora”."}, {"id": 1000354, "trilha": "policial", "materia": "port", "assunto": "Acentuação", "tipo": "pergunta", "frente": "Por que “polícia” é acentuada?", "verso": "É paroxítona terminada em ditongo crescente (-ia).", "explicacao": "Também: história, série, ciência."}, {"id": 1000355, "trilha": "policial", "materia": "port", "assunto": "Acentuação", "tipo": "certo_errado", "frente": "Certo ou errado? Pelo Acordo Ortográfico, “ideia” e “heroico” não têm mais acento.", "verso": "Certo. Caiu o acento dos ditongos abertos “ei” e “oi” nas paroxítonas.", "explicacao": "Nas oxítonas continua: herói, papéis."}, {"id": 1000356, "trilha": "policial", "materia": "port", "assunto": "Morfologia", "tipo": "pergunta", "frente": "Qual o particípio de “aceitar” com “ter” e com “ser”?", "verso": "Com ter/haver: aceitado. Com ser/estar: aceito.", "explicacao": "Mesma regra para entregar (entregado/entregue) e prender (prendido/preso)."}, {"id": 1000357, "trilha": "policial", "materia": "port", "assunto": "Morfologia", "tipo": "pergunta", "frente": "Qual o plural de “cidadão”?", "verso": "Cidadãos.", "explicacao": "Também: irmãos, cristãos. Já “pão” faz pães e “leão” faz leões."}, {"id": 1000358, "trilha": "policial", "materia": "port", "assunto": "Sintaxe", "tipo": "pergunta", "frente": "Em “Choveu muito ontem”, qual o sujeito?", "verso": "Oração sem sujeito (sujeito inexistente).", "explicacao": "Verbos que indicam fenômenos da natureza são impessoais."}, {"id": 1000359, "trilha": "policial", "materia": "port", "assunto": "Sintaxe", "tipo": "pares", "frente": "Voz passiva analítica x sintética.", "verso": "Analítica: ser + particípio (“O réu foi preso pela polícia”). Sintética: verbo + se (“Prenderam-se os réus” = os réus foram presos).", "explicacao": "Na sintética, o verbo concorda com o sujeito paciente."}, {"id": 1000360, "trilha": "policial", "materia": "port", "assunto": "Sintaxe", "tipo": "pergunta", "frente": "Em “Tenho certeza de que passarei”, que oração é “de que passarei”?", "verso": "Oração subordinada substantiva completiva nominal.", "explicacao": "Completa o substantivo “certeza”."}, {"id": 1000361, "trilha": "policial", "materia": "port", "assunto": "Interpretação", "tipo": "pergunta", "frente": "O que é pressuposto no texto?", "verso": "Informação implícita que decorre de uma palavra ou expressão do enunciado.", "explicacao": "“Ele parou de fumar” pressupõe que fumava antes."}, {"id": 1000362, "trilha": "policial", "materia": "port", "assunto": "Interpretação", "tipo": "pares", "frente": "Denotação x conotação.", "verso": "Denotação: sentido literal, de dicionário. Conotação: sentido figurado.", "explicacao": "“O policial é uma rocha” (conotação)."}, {"id": 1000363, "trilha": "policial", "materia": "port", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é metonímia?", "verso": "Troca de uma palavra por outra com a qual tem relação de proximidade (autor pela obra, parte pelo todo, marca pelo produto).", "explicacao": "“Li Machado de Assis” / “Pediu um Bombril”."}, {"id": 1000364, "trilha": "policial", "materia": "port", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é eufemismo?", "verso": "Suavizar uma ideia desagradável.", "explicacao": "“Ele partiu desta para melhor” (morreu)."}, {"id": 1000365, "trilha": "policial", "materia": "port", "assunto": "Redação oficial", "tipo": "pergunta", "frente": "Quais atributos a redação oficial deve ter?", "verso": "Clareza, precisão, objetividade, concisão, coesão e coerência, impessoalidade, formalidade e padronização, e uso da norma-padrão.", "explicacao": "Manual de Redação da Presidência da República (3ª edição, 2018)."}, {"id": 1000366, "trilha": "policial", "materia": "dh", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Quais as características dos direitos humanos?", "verso": "Universalidade, inerência, indivisibilidade, interdependência, inalienabilidade, imprescritibilidade, irrenunciabilidade, historicidade e vedação ao retrocesso.", "explicacao": "Doutrina; Declaração e Programa de Ação de Viena (1993)."}, {"id": 1000367, "trilha": "policial", "materia": "dh", "assunto": "Gerações", "tipo": "pares", "frente": "Direitos de 1ª, 2ª e 3ª geração (dimensão).", "verso": "1ª: liberdade (civis e políticos). 2ª: igualdade (sociais, econômicos e culturais). 3ª: fraternidade (paz, meio ambiente, desenvolvimento).", "explicacao": "Lema da Revolução Francesa: liberdade, igualdade, fraternidade."}, {"id": 1000368, "trilha": "policial", "materia": "dh", "assunto": "Sistema global", "tipo": "pergunta", "frente": "Em que ano foi adotada a Declaração Universal dos Direitos Humanos?", "verso": "1948, pela Assembleia Geral da ONU.", "explicacao": "Resolução 217-A (III), de 10 de dezembro de 1948."}, {"id": 1000369, "trilha": "policial", "materia": "dh", "assunto": "Sistema global", "tipo": "certo_errado", "frente": "Certo ou errado? A Declaração Universal dos Direitos Humanos é um tratado internacional.", "verso": "Errado. Foi adotada como resolução da Assembleia Geral, embora hoje seja vista como costume internacional.", "explicacao": "Doutrina majoritária."}, {"id": 1000370, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Qual o nome do principal tratado do sistema interamericano?", "verso": "Convenção Americana sobre Direitos Humanos (Pacto de São José da Costa Rica), de 1969.", "explicacao": "Promulgada no Brasil pelo Decreto 678/1992."}, {"id": 1000371, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Qual o status do Pacto de São José no Brasil, segundo o STF?", "verso": "Supralegal: abaixo da Constituição e acima das leis.", "explicacao": "STF, RE 466.343. Por isso caiu a prisão do depositário infiel."}, {"id": 1000372, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Quais os órgãos do sistema interamericano de proteção?", "verso": "Comissão Interamericana de Direitos Humanos e Corte Interamericana de Direitos Humanos.", "explicacao": "Convenção Americana, art. 33."}, {"id": 1000373, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Pessoa física pode levar um caso diretamente à Corte Interamericana?", "verso": "Não. Só os Estados-partes e a Comissão podem submeter casos à Corte. O indivíduo peticiona à Comissão.", "explicacao": "Convenção Americana, arts. 44 e 61."}, {"id": 1000374, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "O que prevê o Pacto de São José sobre a pessoa presa?", "verso": "Deve ser conduzida, sem demora, à presença de um juiz.", "explicacao": "Art. 7.5. Base da audiência de custódia."}, {"id": 1000375, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "pergunta", "frente": "Quais princípios regem o uso da força por agentes de segurança?", "verso": "Legalidade, necessidade, proporcionalidade, moderação e conveniência.", "explicacao": "Portaria Interministerial 4.226/2010 e Lei 13.060/2014."}, {"id": 1000376, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "certo_errado", "frente": "Certo ou errado? É legítimo atirar em pessoa em fuga, desarmada, que não representa risco imediato.", "verso": "Errado.", "explicacao": "Portaria Interministerial 4.226/2010, diretriz 4."}, {"id": 1000377, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "certo_errado", "frente": "Certo ou errado? É legítimo atirar contra veículo que fura bloqueio sem representar risco imediato de morte ou lesão.", "verso": "Errado.", "explicacao": "Portaria Interministerial 4.226/2010, diretriz 5."}, {"id": 1000378, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "pergunta", "frente": "O que a Lei 13.060/2014 determina sobre instrumentos de menor potencial ofensivo?", "verso": "Os órgãos de segurança devem priorizar seu uso, desde que não coloquem em risco a integridade física ou psíquica dos policiais.", "explicacao": "Lei 13.060/2014, art. 2º."}, {"id": 1000379, "trilha": "policial", "materia": "dh", "assunto": "Tortura", "tipo": "pergunta", "frente": "O Brasil ratificou a Convenção da ONU contra a Tortura?", "verso": "Sim. Promulgada pelo Decreto 40/1991.", "explicacao": "Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes (1984)."}, {"id": 1000380, "trilha": "policial", "materia": "dh", "assunto": "Tortura", "tipo": "pergunta", "frente": "Ordem de superior hierárquico justifica a tortura?", "verso": "Não. Nenhuma circunstância excepcional ou ordem superior pode ser invocada como justificativa.", "explicacao": "Convenção da ONU contra a Tortura, art. 2º."}, {"id": 1000381, "trilha": "policial", "materia": "dh", "assunto": "Grupos vulneráveis", "tipo": "pergunta", "frente": "O que são as Regras de Mandela?", "verso": "Regras Mínimas da ONU para o Tratamento de Presos, revisadas em 2015.", "explicacao": "Ex.: proíbem confinamento solitário prolongado (mais de 15 dias consecutivos)."}, {"id": 1000382, "trilha": "policial", "materia": "dh", "assunto": "Grupos vulneráveis", "tipo": "pergunta", "frente": "O que são as Regras de Bangkok?", "verso": "Regras da ONU para o tratamento de mulheres presas e medidas não privativas de liberdade para mulheres infratoras.", "explicacao": "Aprovadas em 2010."}, {"id": 1000383, "trilha": "policial", "materia": "dh", "assunto": "CF e direitos humanos", "tipo": "pergunta", "frente": "Quando cabe o incidente de deslocamento de competência para a Justiça Federal?", "verso": "Em grave violação de direitos humanos, para assegurar obrigações de tratados, a pedido do Procurador-Geral da República ao STJ.", "explicacao": "CF, art. 109, § 5º."}, {"id": 1000384, "trilha": "policial", "materia": "dh", "assunto": "CF e direitos humanos", "tipo": "pergunta", "frente": "Que tribunal internacional o Brasil se submete por força da Constituição?", "verso": "O Tribunal Penal Internacional.", "explicacao": "CF, art. 5º, § 4º. Estatuto de Roma."}, {"id": 1000385, "trilha": "policial", "materia": "dh", "assunto": "Tribunal Penal Internacional", "tipo": "pergunta", "frente": "Quais crimes o TPI julga?", "verso": "Genocídio, crimes contra a humanidade, crimes de guerra e crime de agressão.", "explicacao": "Estatuto de Roma, art. 5º."}, {"id": 1000386, "trilha": "policial", "materia": "dh", "assunto": "Tribunal Penal Internacional", "tipo": "pergunta", "frente": "Qual o princípio que rege a atuação do TPI em relação às justiças nacionais?", "verso": "Complementaridade: só atua se o Estado não quiser ou não puder julgar.", "explicacao": "Estatuto de Roma, art. 17."}, {"id": 1000387, "trilha": "policial", "materia": "dh", "assunto": "Pactos de 1966", "tipo": "pares", "frente": "Os dois pactos internacionais de 1966.", "verso": "Pacto Internacional sobre Direitos Civis e Políticos e Pacto Internacional sobre Direitos Econômicos, Sociais e Culturais.", "explicacao": "Com a Declaração Universal, formam a Carta Internacional de Direitos Humanos."}, {"id": 1000388, "trilha": "policial", "materia": "dh", "assunto": "Igualdade", "tipo": "pergunta", "frente": "O que são ações afirmativas?", "verso": "Medidas temporárias para acelerar a igualdade de fato de grupos historicamente discriminados.", "explicacao": "Ex.: cotas raciais em concursos (Lei 12.990/2014, constitucional segundo a ADC 41)."}, {"id": 1000389, "trilha": "policial", "materia": "dh", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "O que é o Sistema Único de Segurança Pública (SUSP)?", "verso": "Sistema que integra os órgãos de segurança da União, Estados, DF e Municípios, com atuação conjunta, coordenada e sistêmica.", "explicacao": "Lei 13.675/2018."}, {"id": 1000390, "trilha": "policial", "materia": "dh", "assunto": "Grupos vulneráveis", "tipo": "pergunta", "frente": "Qual o princípio do melhor interesse da criança?", "verso": "Em todas as decisões que afetem crianças, deve prevalecer o que melhor atenda aos seus interesses.", "explicacao": "Convenção sobre os Direitos da Criança (1989), art. 3º."}, {"id": 1000391, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é phishing?", "verso": "Golpe que usa mensagens ou sites falsos, imitando instituições conhecidas, para roubar senhas e dados.", "explicacao": "Engenharia social."}, {"id": 1000392, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é ransomware?", "verso": "Malware que sequestra os dados (geralmente criptografando) e exige resgate para liberá-los.", "explicacao": "Backups atualizados são a principal defesa."}, {"id": 1000393, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pares", "frente": "Vírus x worm.", "verso": "Vírus: precisa de um arquivo hospedeiro e de execução para se propagar. Worm: propaga-se sozinho pela rede, explorando falhas.", "explicacao": "Cavalo de Troia: parece legítimo e esconde uma função maliciosa."}, {"id": 1000394, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é um keylogger?", "verso": "Programa espião que registra o que é digitado no teclado.", "explicacao": "Screenlogger: captura a tela ou a região clicada."}, {"id": 1000395, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que faz um firewall?", "verso": "Filtra o tráfego da rede, permitindo ou bloqueando conexões conforme regras.", "explicacao": "Não é antivírus: não remove malware."}, {"id": 1000396, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "Quais os pilares da segurança da informação (tríade CID)?", "verso": "Confidencialidade, integridade e disponibilidade.", "explicacao": "Acrescenta-se autenticidade e não repúdio."}, {"id": 1000397, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pares", "frente": "Criptografia simétrica x assimétrica.", "verso": "Simétrica: a mesma chave cifra e decifra. Assimétrica: par de chaves pública e privada.", "explicacao": "A assinatura digital usa a chave privada de quem assina."}, {"id": 1000398, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é autenticação em dois fatores?", "verso": "Exigir dois tipos de prova de identidade: algo que você sabe (senha), tem (celular, token) ou é (biometria).", "explicacao": "Reduz muito o risco de invasão por senha vazada."}, {"id": 1000399, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é backup incremental?", "verso": "Copia só o que mudou desde o último backup de qualquer tipo.", "explicacao": "Diferencial: copia o que mudou desde o último backup completo."}, {"id": 1000400, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pares", "frente": "Internet x intranet x extranet.", "verso": "Internet: rede pública mundial. Intranet: rede privada da organização, com tecnologias da internet. Extranet: parte da intranet acessível a parceiros externos.", "explicacao": "Todas usam TCP/IP."}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select count(*) as cartoes_policial_no_banco from public.cartoes where trilha = 'policial' and ativa;
